/// The exact command that gets the LIVE answer for these refs — printed in every block, including the
/// empty one, because the store is what wins and a reader must always be one copy-paste from it.
pub fn command(refs: &[String]) -> String {
    match refs.first() {
        Some(r) => format!("bsc memory list --link {r}"),
        None => "bsc memory list".to_string(),
    }
}
